        // immediate dismissal in this leaf dialog even if an older layer consumed
        // the key during registration; host modality/focus behavior stays intact.
        if (event.key === 'Escape') {
          event.preventDefault();
          setLabelForm(null);
        }
      }}
    >
      <DialogHeader>
        <DialogTitle>
          {t(
            labelForm?.mode === 'delete'
