        </DialogDescription>
      </DialogHeader>
      {labelForm?.mode === 'delete' ? (
        <div className="flex justify-end gap-2">
          <Button variant="outline" onClick={() => setLabelForm(null)}>
            {t('actions.cancel')}
          </Button>
          <Button
            variant="destructive"
            onClick={() => void mutateLabel('delete', labelForm.label)}
