                      </DropdownMenuContent>
                    </DropdownMenu>
                    {labelDialogContent}
                  </Dialog>
                )}
              </li>
            ))}
          </ul>
        </>
      )}
    </div>
  );

  return (
    <div
      ref={mailboxRef}
      className={cn(
        'maily-mailbox @container/mailbox border-border bg-background text-foreground flex h-[42rem] max-h-[calc(100dvh-2rem)] min-h-0 min-w-0 overflow-hidden rounded-lg border',
        className
      )}
    >
      {!compact && (
        <aside
          aria-label={t('navigation.menu')}
          className="bg-muted/30 border-border flex w-52 shrink-0 flex-col overflow-y-auto border-r"
        >
          {navigation}
        </aside>
      )}
      <div className="flex min-h-0 min-w-0 flex-1 flex-col">
        <div className="border-border flex shrink-0 items-center border-b">
          {compact && (
            <Sheet open={navigationOpen} onOpenChange={setNavigationOpen}>
              <SheetTrigger asChild>
                <MailboxIconButton
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="ml-1 size-11 shrink-0"
                  aria-label={t('navigation.menu')}
                >
                  <IconPlaceholder
  lucide="Menu"
  tabler="IconMenu2"
  hugeicons="Menu01Icon"
  phosphor="List"
  remixicon="RiMenuLine"
  className="size-5"
/>
                </MailboxIconButton>
              </SheetTrigger>
              <SheetContent
                side="left"
                showCloseButton={false}
                aria-describedby={undefined}
                className="flex w-72 max-w-[calc(100vw-3rem)] flex-col gap-0 p-0"
              >
                <SheetHeader className="flex-row items-center justify-between p-3">
                  <SheetTitle>{t('navigation.menu')}</SheetTitle>
                  <SheetClose asChild>
                    <MailboxIconButton
                      variant="ghost"
                      size="icon"
                      className="size-11"
                      aria-label={t('navigation.close')}
                    >
                      <IconPlaceholder
  lucide="X"
  tabler="IconX"
  hugeicons="Cancel01Icon"
  phosphor="X"
  remixicon="RiCloseLine"
  className="size-4"
/>
                    </MailboxIconButton>
                  </SheetClose>
                </SheetHeader>
                <div className="flex min-h-0 flex-1 flex-col overflow-y-auto">
                  {navigation}
                </div>
              </SheetContent>
            </Sheet>
          )}
          <div className="min-w-0 flex-1 p-2">
            <InputGroup className="bg-muted/30 h-11">
              <InputGroupAddon>
                <IconPlaceholder
  lucide="Search"
  tabler="IconSearch"
  hugeicons="Search01Icon"
  phosphor="MagnifyingGlass"
  remixicon="RiSearchLine"
  className="size-4"
/>
              </InputGroupAddon>
              <InputGroupInput
                value={search}
                onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
                  setSearch(event.target.value);
                  if (props.search !== undefined) return;
                  setGlobalSearch(!!event.target.value.trim());
                  setSelectedLabelId(null);
                }}
                placeholder={t('searchPlaceholder')}
                aria-label={t('searchPlaceholder')}
                className="h-10 min-w-0 px-1.5 py-0 text-base"
              />
              <InputGroupAddon align="inline-end">
                {(search || Object.keys(searchFields).length > 0) && (
