                    size="icon"
                    variant="ghost"
                    className="size-11"
                    aria-label={t('search.clear')}
                    onClick={() => {
                      setSearch('');
                      if (props.search !== undefined) return;
                      setSearchFields({});
                      setGlobalSearch(false);
