                >
                  <PopoverTrigger asChild>
                    <MailboxIconButton
                      type="button"
                      size="icon"
                      variant="ghost"
                      className="size-11"
                      aria-label={t('search.advanced')}
                    >
                      <IconPlaceholder
  lucide="Filter"
  tabler="IconFilter"
  hugeicons="FilterIcon"
  phosphor="Funnel"
  remixicon="RiFilter3Line"
  className="size-4"
/>
                    </MailboxIconButton>
