                    </form>
                  </PopoverContent>
                </Popover>
              </InputGroupAddon>
              {refreshing && (
                <InputGroupAddon align="inline-end">
                  <IconPlaceholder
  lucide="LoaderCircleIcon"
  tabler="IconLoader2"
  hugeicons="Loading03Icon"
  phosphor="CircleNotch"
  remixicon="RiLoader2Line"
  className="size-4 animate-spin"
                    aria-label={t('refresh')}
/>
                </InputGroupAddon>
              )}
            </InputGroup>
            {!globalSearch &&
              dataSource.emptyFolder &&
              (folder === 'trash' || folder === 'spam') && (
                <Popover
                  open={emptyConfirmOpen}
                  onOpenChange={setEmptyConfirmOpen}
                >
                  <PopoverTrigger asChild>
                    <Button
                      type="button"
                      variant="destructive"
                      size="sm"
                      className="mt-2"
                      disabled={emptyingFolder}
                    >
                      {t(
                        folder === 'trash'
                          ? 'actions.emptyTrash'
                          : 'actions.deleteAllSpam'
                      )}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent
                    align="start"
                    className="w-72 max-w-[calc(100vw-2rem)] space-y-3"
                  >
                    <p className="text-sm">
                      {t(
                        folder === 'trash'
                          ? 'confirm.emptyTrash'
                          : 'confirm.deleteAllSpam'
                      )}
                    </p>
                    <div className="flex justify-end gap-2">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => setEmptyConfirmOpen(false)}
                      >
                        {t('actions.cancel')}
                      </Button>
                      <Button
                        type="button"
                        variant="destructive"
                        size="sm"
                        onClick={() => {
                          setEmptyConfirmOpen(false);
                          void emptyFolder();
                        }}
                      >
                        {t('actions.confirm')}
                      </Button>
                    </div>
                  </PopoverContent>
                </Popover>
              )}
          </div>
        </div>
        {pendingNavigation && (
          <Dialog
            open
            onOpenChange={(open) => {
              if (!open) setPendingNavigation(null);
            }}
          >
            <DialogContent
              showCloseButton={false}
              className="sm:max-w-sm"
              aria-describedby={undefined}
              onKeyDown={(event) => {
                if (event.key === 'Escape') {
                  event.preventDefault();
                  setPendingNavigation(null);
                }
              }}
            >
              <DialogHeader>
                <DialogTitle>{t('compose.unsavedConfirm')}</DialogTitle>
              </DialogHeader>
              <div className="flex justify-end gap-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => setPendingNavigation(null)}
                >
                  {t('compose.stay')}
                </Button>
                <Button
                  type="button"
                  variant="destructive"
                  onClick={() => {
                    const navigate = pendingNavigation;
                    composeDirty.current = false;
                    setPendingNavigation(null);
