            {selectedIds.length > 0 && (
              <div className="flex min-w-0 flex-wrap items-center gap-1">
                <span className="sr-only">
                  {t('selection.count', { count: selectedIds.length })}
                </span>
                {dataSource.runBulkMessageAction &&
                  Array.from(new Set(messageActions))
                    .filter((action) =>
                      [
                        'archive',
                        'delete',
                        'reportSpam',
                        'markRead',
                        'markUnread',
                        'restore',
                        'notSpam',
                        'deleteForever',
                      ].includes(action)
                    )
                    .filter((action) => {
                      if (action === 'markRead')
                        return messages.items.some(
                          (row) => selectedIds.includes(row.id) && row.isUnread
                        );
                      if (action === 'markUnread')
                        return messages.items.some(
                          (row) => selectedIds.includes(row.id) && !row.isUnread
                        );
                      if (action === 'archive')
                        return !globalSearch && folder === 'inbox';
                      if (action === 'restore')
                        return (
                          folder === 'trash' ||
                          folder === 'allMail' ||
                          folder === 'starred'
                        );
                      if (action === 'notSpam')
                        return !globalSearch && folder === 'spam';
                      if (action === 'deleteForever')
                        return (
                          !globalSearch &&
                          (folder === 'trash' || folder === 'spam')
                        );
                      if (action === 'delete' || action === 'reportSpam')
                        return (
                          globalSearch ||
                          (folder !== 'trash' && folder !== 'spam')
                        );
                      return true;
                    })
                    .map((action) => (
                      <MailboxIconButton
                        key={action}
                        type="button"
                        size="icon"
                        className="size-11"
                        variant="ghost"
                        aria-label={t(MESSAGE_ACTION_METADATA[action].label)}
                        disabled={!!messageActionPending}
                        onClick={() =>
                          void runBulkAction(
                            action,
                            MESSAGE_ACTION_METADATA[action].value
                          )
                        }
                      >
                        {MESSAGE_ACTION_METADATA[action].icon('size-4')}
                      </MailboxIconButton>
                    ))}
                {mailboxLabels.length > 0 &&
                  (dataSource.applyLabel || dataSource.removeLabel) && (
                    <Popover>
                      <PopoverTrigger asChild>
                        <MailboxIconButton
                          type="button"
                          size="icon"
                          variant="ghost"
                          className="size-11"
                          aria-label={t(
                            dataSource.applyLabel
                              ? 'actions.applyLabel'
                              : 'actions.removeLabel'
                          )}
                        >
                          <IconPlaceholder
  lucide="Tag"
  tabler="IconTag"
  hugeicons="Tag01Icon"
  phosphor="Tag"
  remixicon="RiPriceTagLine"
  className="size-4"
/>
                        </MailboxIconButton>
                      </PopoverTrigger>
                      <PopoverContent align="start" className="w-56 space-y-1">
                        {mailboxLabels.map((label, labelIndex) => {
                          const checked = messages.items
                            .filter((row) => selectedIds.includes(row.id))
                            .every(
                              (row) =>
                                row.labels?.includes(label.id) ||
                                row.labels?.includes(label.name)
                            );
                          return (
                            <Field
                              key={label.id}
                              orientation="horizontal"
                              className="hover:bg-accent gap-2 rounded-sm px-2 py-1.5"
                            >
                              <Checkbox
                                id={`${labelInputId}-apply-${labelIndex}`}
                                checked={checked}
                                disabled={
                                  checked
                                    ? !dataSource.removeLabel
                                    : !dataSource.applyLabel
                                }
                                onCheckedChange={(value) =>
                                  void applyLabelToSelection(
                                    label.id,
                                    value !== true
                                  )
                                }
                              />
                              <FieldLabel
                                htmlFor={`${labelInputId}-apply-${labelIndex}`}
                                className="min-w-0 truncate"
                              >
                                {label.name}
                              </FieldLabel>
                            </Field>
                          );
                        })}
                      </PopoverContent>
                    </Popover>
                  )}
              </div>
            )}
            {selectedIds.length === 0 && (
              <MailboxIconButton
                type="button"
                variant="ghost"
                size="icon"
                className="size-11"
                aria-label={t('refresh')}
                disabled={refreshing || loadingMore}
                onClick={() => void refreshMailbox()}
              >
                <IconPlaceholder
  lucide="RotateCwIcon"
  tabler="IconRepeat"
  hugeicons="RepeatIcon"
  phosphor="Repeat"
  remixicon="RiRepeatLine"
  className={cn('size-4', refreshing && 'animate-spin')}
/>
              </MailboxIconButton>
            )}
            <div className="ml-auto flex items-center gap-1">
              <span
                className="text-muted-foreground whitespace-nowrap px-1 text-xs tabular-nums"
                aria-live="polite"
              >
                {t(
                  pageTotal === undefined
                    ? 'pagination.range'
                    : 'pagination.rangeWithTotal',
                  { start: pageStart, end: pageEnd, total: pageTotal ?? 0 }
                )}
              </span>
              <MailboxIconButton
                type="button"
                variant="ghost"
                size="icon"
                className="size-11"
                aria-label={t('pagination.previous')}
                disabled={
                  !hasPreviousPage ||
                  messagesLoading ||
                  loadingMore ||
                  refreshing
                }
                onClick={() => void changePage('previous')}
              >
                <IconPlaceholder
  lucide="ChevronRight"
  tabler="IconChevronRight"
  hugeicons="ChevronRightIcon"
  phosphor="CaretRight"
  remixicon="RiArrowRightSLine"
  className="size-4 rotate-180"
/>
              </MailboxIconButton>
              <MailboxIconButton
                type="button"
                variant="ghost"
                size="icon"
                className="size-11"
                aria-label={t('pagination.next')}
                disabled={
                  !messages.nextCursor ||
                  messagesLoading ||
                  loadingMore ||
                  refreshing
                }
                onClick={() => void changePage('next')}
              >
                <IconPlaceholder
  lucide="ChevronRight"
  tabler="IconChevronRight"
  hugeicons="ChevronRightIcon"
  phosphor="CaretRight"
  remixicon="RiArrowRightSLine"
  className="size-4"
/>
              </MailboxIconButton>
            </div>
          </div>
          <ScrollArea className="min-h-0 flex-1">
            <MessageList
              folder={globalSearch ? 'allMail' : folder}
              labels={labels}
              rows={messages.items}
              isLoading={messagesLoading}
              selectedId={selectedId}
              selectedIds={selectedIds}
              onSelect={(row) => {
                lastMessageTrigger.current =
                  document.activeElement as HTMLElement;
                selectMessage(row);
              }}
              onToggleSelection={
                dataSource.runBulkMessageAction ||
                dataSource.applyLabel ||
                dataSource.removeLabel
                  ? (ids) =>
                      setSelectedIds((current) =>
                        ids.every((id) => current.includes(id))
                          ? current.filter((id) => !ids.includes(id))
                          : [...new Set([...current, ...ids])]
                      )
                  : undefined
              }
              onToggleFavorite={
                enabledMessageActions.includes('favorite')
                  ? (row) =>
                      void runMessageAction(row, 'favorite', !row.isFavorite)
                  : undefined
              }
              formatDate={formatDate}
            />
          </ScrollArea>
        </div>
        {detailOpen && (
          <div className="flex min-h-0 min-w-0 flex-1 flex-col">
            {composeOpen ? (
              <>
                <div className="border-border flex min-h-12 items-center border-b px-2">
                  {backButton}
                </div>
                <ScrollArea className="min-h-0 flex-1">
                  {!composeHydrated ? (
                    <div role="status" className="p-5">
                      {t('loading')}
                    </div>
                  ) : (
                    <Compose
                      key={composeSession}
                      initialValues={initialComposeValues}
                      labels={labels}
                      loadContactSuggestions={loadContactSuggestions}
                      defaultBodyMode={defaultComposeBodyMode}
                      allowBodyModeSwitch={allowComposeBodyModeSwitch}
                      editorProps={composeEditorProps}
                      isExistingDraft={!!composeDraftId}
                      isSaving={saving}
                      isSendUnresolved={sendUnresolved}
                      isSending={sending}
                      isDiscarding={discarding}
                      ownershipToken={lifetime}
                      uploadAttachment={dataSource.uploadAttachment}
                      discardUploadedAttachment={
                        dataSource.discardUploadedAttachment
                      }
                      onError={onError}
                      onDirtyChange={(dirty) => {
                        composeDirty.current = dirty;
                      }}
                      onSave={saveDraft}
                      onSend={sendDraft}
                      onDiscard={discardDraft}
                    />
                  )}
                </ScrollArea>
              </>
            ) : selectedId ? (
              <MessageReader
                key={selectedId}
                backButton={backButton}
                getMessageSource={dataSource.getMessageSource}
                thread={thread}
                detail={detail}
                isLoading={detailLoading}
                labels={labels}
                formatDate={formatDate}
                messageActions={enabledMessageActions.filter((action) => {
                  if (action === 'restore')
                    return (
                      folder === 'trash' ||
                      folder === 'allMail' ||
                      folder === 'starred'
                    );
                  if (action === 'notSpam')
                    return !globalSearch && folder === 'spam';
                  if (action === 'deleteForever')
                    return (
                      !globalSearch && (folder === 'trash' || folder === 'spam')
                    );
                  if (
                    action === 'delete' ||
                    action === 'archive' ||
                    action === 'reportSpam'
                  ) {
                    if (action === 'archive')
                      return !globalSearch && folder === 'inbox';
                    return (
                      globalSearch || (folder !== 'trash' && folder !== 'spam')
                    );
                  }
                  return true;
                })}
                actionPending={messageActionPending}
                onReply={openReply}
                onReplyAll={(message) => openReply(message, true)}
                onForward={openForward}
                onRunAction={runMessageAction}
                downloadAttachment={dataSource.downloadAttachment}
                onError={onError}
              />
            ) : null}
          </div>
        )}
      </div>
    </div>
  );
}

export const InboxOutboxView = MailboxView;

function MessageList(props: {
  folder: MailyMailboxFolder;
  labels: MailyMailboxLabels;
  rows: MailyMailboxMessageRow[];
  isLoading: boolean;
  selectedId: string | null;
  selectedIds: string[];
  onSelect: (row: MailyMailboxMessageRow) => void;
  onToggleSelection?: (ids: string[]) => void;
  onToggleFavorite?: (row: MailyMailboxMessageRow) => void;
  formatDate: (date: string | Date, mode: 'short' | 'long') => string;
}) {
  const {
    folder,
    labels,
    rows,
    isLoading,
    selectedId,
    selectedIds,
    onSelect,
    onToggleSelection,
    onToggleFavorite,
    formatDate,
  } = props;
  const t = (
    key: MailyMailboxLabelKey,
    vars?: Record<string, string | number>
  ) => interpolate(labels[key], vars);

  if (isLoading) {
    return (
      <div className="text-muted-foreground flex h-40 items-center justify-center gap-2 text-sm">
        <IconPlaceholder
  lucide="LoaderCircleIcon"
  tabler="IconLoader2"
  hugeicons="Loading03Icon"
  phosphor="CircleNotch"
  remixicon="RiLoader2Line"
  className="size-4 animate-spin"
/>
        {t('loading')}
      </div>
    );
  }

  if (rows.length === 0) {
    return <EmptyState className="h-full" title={t(`empty.${folder}`)} />;
  }

  return (
    <div className="@container/list min-w-0 [contain:inline-size]">
      <ul className="divide-border divide-y">
        {groupMailboxMessagesByThread(rows).map((conversation) => {
          const groupRows = conversation.messages;
          const row = groupRows[groupRows.length - 1];
          const conversationIds = groupRows.map((item) => item.id);
          const active = groupRows.some((item) => item.id === selectedId);
          const allSelected = conversationIds.every((id) =>
            selectedIds.includes(id)
          );
          const display =
            row.direction === 'in'
              ? row.fromAddress
              : formatRecipients(row.toAddresses);

          return (
            <li
              key={conversation.threadId ?? row.id}
              className={cn(
                'flex min-w-0 items-stretch',
                (active || allSelected) && 'bg-accent',
                !row.isUnread && 'bg-muted/20'
              )}
            >
              {onToggleSelection && (
                <Label className="flex size-11 shrink-0 items-center justify-center">
                  <MailboxTooltip
                    label={t(
                      allSelected
                        ? 'actions.deselectConversation'
                        : 'actions.selectConversation',
                      { subject: row.subject || t('message.noSubject') }
                    )}
                  >
                    <Checkbox
                      aria-label={t(
                        allSelected
                          ? 'actions.deselectConversation'
                          : 'actions.selectConversation',
                        { subject: row.subject || t('message.noSubject') }
                      )}
                      checked={allSelected}
                      onCheckedChange={() =>
                        onToggleSelection?.(conversationIds)
                      }
                    />
                  </MailboxTooltip>
                </Label>
              )}
              {onToggleFavorite && (
                <MailboxIconButton
                  type="button"
                  size="icon"
                  variant="ghost"
                  className="size-11 shrink-0"
                  aria-label={t(
                    row.isFavorite ? 'actions.unfavorite' : 'actions.favorite'
                  )}
                  onClick={() => onToggleFavorite(row)}
                >
                  <IconPlaceholder
  lucide="Star"
  tabler="IconStar"
  hugeicons="StarIcon"
  phosphor="Star"
  remixicon="RiStarLine"
  className={cn(
                      'text-muted-foreground size-4',
                      row.isFavorite && 'fill-current text-amber-500'
                    )}
/>
                </MailboxIconButton>
              )}
              <Button
                type="button"
                variant="ghost"
                onClick={() => onSelect(row)}
                className={cn(
                  'hover:bg-accent @3xl/list:grid-cols-[12rem_minmax(0,1fr)_auto] grid h-auto min-h-11 min-w-0 flex-1 grid-cols-[minmax(0,1fr)_auto] items-center gap-x-3 gap-y-0.5 whitespace-normal rounded-none px-2 py-2 text-left font-normal',
                  active && 'bg-accent'
                )}
              >
                <span
                  className={cn(
                    'col-start-1 row-start-1 min-w-0 truncate text-sm',
                    row.isUnread ? 'font-semibold' : 'font-medium'
                  )}
                >
                  {display || t('message.unknownSender')}
                </span>
                <span className="@3xl/list:col-span-1 @3xl/list:col-start-2 @3xl/list:row-start-1 @3xl/list:flex-row @3xl/list:items-center @3xl/list:gap-2 col-span-2 col-start-1 row-start-2 flex min-w-0 flex-col">
                  <span className="@3xl/list:shrink-0 @3xl/list:max-w-[65%] flex min-w-0 items-center gap-1.5">
                    {row.isFavorite && !onToggleFavorite && (
                      <IconPlaceholder
  lucide="Star"
  tabler="IconStar"
  hugeicons="StarIcon"
  phosphor="Star"
  remixicon="RiStarLine"
  className="size-3.5 shrink-0 fill-current text-amber-500"
/>
                    )}
                    <span
                      className={cn(
                        'truncate text-sm',
                        row.isUnread && 'font-semibold'
                      )}
                    >
                      {row.subject || t('message.noSubject')}
                    </span>
                    {groupRows.length > 1 && (
                      <Badge variant="outline">{groupRows.length}</Badge>
                    )}
                    {row.hasAttachments && (
                      <IconPlaceholder
  lucide="Paperclip"
  tabler="IconPaperclip"
  hugeicons="AttachmentIcon"
  phosphor="Paperclip"
  remixicon="RiAttachmentLine"
  className="text-muted-foreground size-3 shrink-0"
/>
                    )}
                  </span>
                  {row.snippet && (
                    <span className="text-muted-foreground min-w-0 truncate text-sm">
                      {row.snippet}
                    </span>
                  )}
                </span>
                <span className="text-muted-foreground @3xl/list:col-start-3 col-start-2 row-start-1 text-xs">
                  {formatDate(row.createdAt, 'short')}
                </span>
                {(row.status === 'failed' || row.status === 'dsn') && (
                  <Badge variant="destructive" className="self-start">
                    {t('message.bounced')}
                  </Badge>
                )}
                {row.status === 'queued' && (
                  <Badge variant="outline" className="self-start">
                    {t('message.queued')}
                  </Badge>
                )}
              </Button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

/** Source is rendered as escaped text, never as HTML or an iframe. */
function MessageSource(props: {
  messageId: string;
  getSource: NonNullable<MailyMailboxDataSource['getMessageSource']>;
  labels: MailyMailboxLabels;
  onBack: () => void;
  onError: MailyMailboxViewProps['onError'];
}) {
  const { messageId, getSource, labels, onBack, onError } = props;
  const [source, setSource] = React.useState<string | null>(null);
  const [failed, setFailed] = React.useState(false);
  const [attempt, setAttempt] = React.useState(0);
  const errorHandler = React.useRef(onError);
  errorHandler.current = onError;
  React.useEffect(() => {
    let active = true;
    setSource(null);
    setFailed(false);
    Promise.resolve()
      .then(() => getSource(messageId))
      .then(
        (value) => {
          if (active) setSource(value);
        },
        (error) => {
          if (!active) return;
          setFailed(true);
          errorHandler.current?.(error, 'messageSource');
        }
      );
    return () => {
      active = false;
    };
  }, [getSource, messageId, attempt]);

  return (
    <section
      className="flex h-full min-h-0 flex-col"
      aria-label={labels['actions.showOriginal']}
    >
      <div className="border-border flex shrink-0 items-center gap-2 border-b p-3">
        <Button variant="outline" onClick={onBack}>
          {labels['source.back']}
        </Button>
      </div>
      {failed ? (
        <div className="space-y-3 p-5">
          <p role="alert" className="text-sm">
            {labels['source.error']}
          </p>
          <Button
            variant="outline"
            onClick={() => setAttempt((value) => value + 1)}
          >
            {labels['source.retry']}
          </Button>
        </div>
      ) : source === null ? (
        <p role="status" className="text-muted-foreground p-5 text-sm">
          {labels.loading}
        </p>
      ) : (
        <ScrollArea className="min-h-0 flex-1">
          <pre
            className="whitespace-pre-wrap break-all p-5 font-mono text-xs"
            tabIndex={0}
          >
            {source}
          </pre>
        </ScrollArea>
      )}
    </section>
  );
}

function MessageReader(props: {
  backButton: React.ReactNode;
  getMessageSource: MailyMailboxDataSource['getMessageSource'];
  thread?: MailyMailboxThread | null;
  detail: MailyMailboxMessageDetail | null;
  isLoading: boolean;
  labels: MailyMailboxLabels;
  formatDate: (date: string | Date, mode: 'short' | 'long') => string;
  messageActions: readonly MailyMailboxMessageAction[];
  actionPending: MailyMailboxMessageAction | null;
  onReply: (detail: MailyMailboxMessageDetail) => void;
  onReplyAll: (detail: MailyMailboxMessageDetail) => void;
  onForward: (detail: MailyMailboxMessageDetail) => void;
  downloadAttachment: MailyMailboxDataSource['downloadAttachment'];
  onError: MailyMailboxViewProps['onError'];
  onRunAction: (
    detail: MailyMailboxMessageDetail,
    action: MailyMailboxMessageAction,
    value?: string | boolean | null
  ) => Promise<void>;
}) {
  const {
    detail,
    isLoading,
    labels,
    formatDate,
    messageActions,
    actionPending,
    onReply,
    onReplyAll,
    onForward,
    onRunAction,
  } = props;
  const t = (
    key: MailyMailboxLabelKey,
    vars?: Record<string, string | number>
  ) => interpolate(labels[key], vars);

  const [showSource, setShowSource] = React.useState(false);
  const runReaderAction: typeof onRunAction = async (
    message,
    action,
    value
  ) => {
    if (action === 'showOriginal' && props.getMessageSource) {
      setShowSource(true);
      return;
    }
    await onRunAction(message, action, value);
  };

  if (showSource && detail && props.getMessageSource) {
    return (
      <MessageSource
        messageId={detail.id}
        getSource={props.getMessageSource}
        labels={labels}
        onBack={() => setShowSource(false)}
        onError={props.onError}
      />
    );
  }

  if (isLoading) {
    return (
      <>
        <div className="border-border flex min-h-12 shrink-0 items-center border-b px-2">
          {props.backButton}
        </div>
        <div
          role="status"
          className="text-muted-foreground flex flex-1 items-center justify-center gap-2 text-sm"
        >
          <IconPlaceholder
  lucide="LoaderCircleIcon"
  tabler="IconLoader2"
  hugeicons="Loading03Icon"
  phosphor="CircleNotch"
  remixicon="RiLoader2Line"
  className="size-4 animate-spin"
/>
          {t('loading')}
        </div>
      </>
    );
  }

  if (!detail)
    return (
      <div className="border-border flex min-h-12 items-center border-b px-2">
        {props.backButton}
      </div>
    );

  const threadMessages =
    props.thread?.threadId && props.thread.threadId === detail.threadId
      ? props.thread.messages
      : [detail];
  const labelsToShow = detail.labels ?? [];
  const isFavorite = detail.isFavorite ?? false;
  const enabledActions = new Set(messageActions);
  const toolbarLeadingActions = TOOLBAR_LEADING_MESSAGE_ACTIONS.filter(
    (action) => enabledActions.has(action)
  );
  const toolbarTrailingActions = TOOLBAR_TRAILING_MESSAGE_ACTIONS.filter(
    (action) => enabledActions.has(action)
  );
  const headerActions = HEADER_MESSAGE_ACTIONS.filter((action) =>
    enabledActions.has(action)
  );
  const run = (
    action: MailyMailboxMessageAction,
    value?: string | boolean | null
  ) => runReaderAction(detail, action, value);
  const actionLabel = (
    action: MailyMailboxMessageAction,
    mode: 'button' | 'menu'
  ) => {
    if (action === 'favorite' && isFavorite) return t('actions.unfavorite');
    if (action === 'showOriginal' && props.getMessageSource)
      return t('actions.showOriginal');
    const metadata = MESSAGE_ACTION_METADATA[action];
    return t(
      mode === 'button' && metadata.toolbarLabel
        ? metadata.toolbarLabel
        : metadata.label
    );
  };
  const actionValue = (action: MailyMailboxMessageAction) => {
    if (action === 'favorite') return !isFavorite;
    return MESSAGE_ACTION_METADATA[action].value;
  };
  const actionIconClassName = (action: MailyMailboxMessageAction) =>
    cn(
      'size-4',
      action === 'favorite' && isFavorite && 'fill-current text-amber-500'
    );
  const renderActionButton = (action: MailyMailboxMessageAction) => (
    <MessageActionButton
      key={action}
      label={actionLabel(action, 'button')}
      className={
        action === 'react' ? '@md/mailbox:inline-flex hidden' : undefined
      }
      pending={actionPending === action}
      pressed={action === 'favorite' ? isFavorite : undefined}
      onClick={() => run(action, actionValue(action))}
    >
      {action === 'showOriginal' && !props.getMessageSource ? (
        <IconPlaceholder
  lucide="ExternalLink"
  tabler="IconExternalLink"
  hugeicons="ArrowUpRight01Icon"
  phosphor="ArrowSquareOut"
  remixicon="RiExternalLinkLine"
  className="size-4"
/>
      ) : (
        MESSAGE_ACTION_METADATA[action].icon(actionIconClassName(action))
      )}
    </MessageActionButton>
  );

  return (
    <article className="flex h-full min-h-0 flex-col overflow-hidden">
      <div className="border-border flex shrink-0 flex-wrap items-center justify-between gap-1 border-b px-2 py-1">
        <div className="flex flex-wrap items-center gap-1">
          {props.backButton}
          {toolbarLeadingActions.map(renderActionButton)}
        </div>
        <div className="flex items-center gap-1">
          {toolbarTrailingActions.map(renderActionButton)}
        </div>
      </div>

      <ScrollArea className="min-h-0 flex-1">
        <div className="min-w-0 [contain:inline-size]">
          <div className="@lg/mailbox:px-5 flex flex-col gap-4 px-3 pt-4">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div className="min-w-0">
                <div className="flex flex-wrap items-center gap-2">
                  <h2 className="min-w-0 break-words text-xl font-semibold leading-tight [overflow-wrap:anywhere]">
                    {detail.subject || t('message.noSubject')}
                  </h2>
                  {labelsToShow.map((label) => (
                    <Badge key={label} variant="secondary">
                      {label}
                    </Badge>
                  ))}
                </div>
              </div>
              <div className="flex min-w-0 flex-wrap items-center gap-1">
                {headerActions.map(renderActionButton)}
                <MessageActionButton
                  label={t('actions.reply')}
                  pending={false}
                  onClick={() => onReply(detail)}
                >
                  <IconPlaceholder
  lucide="Reply"
  tabler="IconCornerUpLeft"
  hugeicons="MailReply01Icon"
  phosphor="ArrowBendUpLeft"
  remixicon="RiReplyLine"
  className="size-4"
/>
                </MessageActionButton>
                <MessageActionButton
                  className={
                    messageActions.length > 0
                      ? '@md/mailbox:inline-flex hidden'
                      : undefined
                  }
                  label={t('actions.replyAll')}
                  pending={false}
                  onClick={() => onReplyAll(detail)}
                >
                  <IconPlaceholder
  lucide="ReplyAll"
  tabler="IconCornerUpLeftDouble"
  hugeicons="MailReplyAll01Icon"
  phosphor="ArrowBendDoubleUpLeft"
  remixicon="RiReplyAllLine"
  className="size-4"
/>
                </MessageActionButton>
                <MessageActionButton
                  className={
                    messageActions.length > 0
                      ? '@md/mailbox:inline-flex hidden'
                      : undefined
                  }
                  label={t('actions.forward')}
                  pending={false}
                  onClick={() => onForward(detail)}
                >
